 $('ordersContent').innerHTML=`<div class="ops-toolbar">${ops.orders.some(o=>o.status==='Draft')?btn('Review automatic draft →','order',ops.orders.find(o=>o.status==='Draft').id,'primary'):''} ${btn('Manual purchase order','newOrder','','secondary')} ${parts.some(p=>p.onOrder>0&&p.received<p.qty&&!['Completed','On Hold'].includes(ops.jobs[p.assetId]?.status))?btn('Receive all orders','receiveOrders','','primary'):''} <span class="section-note">Costs are entered manually in GBP. This does not purchase anything from suppliers automatically.</span></div><div class="section-panel ops-table-wrap"><table class="asset-table"><thead><tr><th>Order</th><th>Supplier</th><th>Lines</th><th>Expected</th><th>Cost</th><th>Status</th><th></th></tr></thead><tbody>${ops.orders.map(o=>`<tr><td><b>${esc(o.id)}</b><div class="section-note">${esc(o.reference||'No reference')}</div></td><td>${esc(o.supplier||'Choose supplier')}</td><td>${o.lines.length}</td><td>${esc(o.expectedAt||'Not set')}</td><td>£${Number(o.cost||0).toFixed(2)}</td><td>${pill(orderState(o))}</td><td>${btn(o.status==='Draft'?'Review draft →':'Details →','order',o.id)} ${btn('Delete','deleteOrder',o.id)}</td></tr>`).join('')||'<tr><td colspan="7">No purchase orders yet.</td></tr>'}</tbody></table></div>`;
 $('deliveriesContent').innerHTML=`<div class="ops-toolbar"><span class="section-note">Use Receive to book partial or complete deliveries. Received stock updates the linked laptop immediately.</span>${parts.some(p=>p.onOrder>0&&p.received<p.qty&&!['Completed','On Hold'].includes(ops.jobs[p.assetId]?.status))?btn('Receive all orders','receiveOrders','','primary'):''}</div><div class="section-panel ops-table-wrap"><table class="asset-table"><thead><tr><th>Order / Supplier</th><th>Part</th><th>Asset</th><th>Expected date</th><th>Received</th><th>Action</th></tr></thead><tbody>${ops.orders.filter(o=>o.status!=='Draft').flatMap(o=>o.lines.filter(l=>l.received<l.qty).map(l=>`<tr><td><b>${esc(o.id)}</b><div class="section-note">${esc(o.supplier)}</div></td><td>${esc(l.name)}</td><td>${esc(l.assetId)}</td><td>${esc(o.expectedAt||'—')}</td><td>${l.received} / ${l.qty}</td><td>${btn('Receive →','receive',o.id+'|'+l.assetId+'|'+l.partId,'primary')}</td></tr>`)).join('')||'<tr><td colspan="6">No deliveries outstanding.</td></tr>'}</tbody></table></div>`;
 $('qcContent').innerHTML=jobsTable(js.filter(j=>['Quality Control','Ready for Repair','Repair In Progress','On Hold'].includes(j.status)))+'<p class="section-note">Complete the four QC checks on each job. The app blocks completion while repairs or QC remain unfinished.</p>';
