function worksheetMarkup(id){const a=item(id),j=ops.jobs[id];if(!a)throw Error('Unknown asset');
 const qr=window.ApexAssetLabelQR.qrCodeSvg(window.ApexAssetLabelQR.makePayload(a));
 const reqs=j?.parts||a.refurbishment?.repairs||[];
 const ref=a.refurbishment||{};const latest=Array.isArray(ref.reports)?ref.reports.find(r=>r.key===ref.latestKey)||ref.reports.at(-1):ref;const notes=latest?.notes||ref.notes||'';const cos=latest?.cosmeticIssues||ref.cosmeticIssues||'';
 return `<div class="ops-sheet"><header><div><b>APEX / REFURB MANAGEMENT</b><h1>DEVICE REPAIR WORKSHEET</h1><small>Print date: ${esc(new Date().toLocaleDateString('en-GB'))} · A4</small></div><div class="ops-paper-qr">${qr}</div></header><h2>${esc(deviceName(a))}</h2><div class="ops-sheet-cols"><span><b>ASSET ID</b><br>${esc(a.id)}</span><span><b>SERIAL</b><br>${esc(a.serial||'—')}</span><span><b>CONDITION</b><br>${esc(a.condition)}</span><span><b>JOB STATUS</b><br>${esc(j?.status||'Received')}</span></div><h3>REPLACEMENT PARTS & REPAIRS</h3><table><thead><tr><th style="width:12mm">✓</th><th>Part / action required</th><th style="width:13mm">Qty</th></tr></thead><tbody>${reqs.map(p=>`<tr><td>☐</td><td>${esc(p.name)}</td><td>${Number(p.qty||p.quantity)||1}</td></tr>`).join('')||'<tr><td>☐</td><td>No replacement parts recorded</td><td>—</td></tr>'}</tbody></table><h3>COSMETIC / REFURB NOTES</h3><p class="ops-sheet-note">${esc(cos||notes||'No inspection notes submitted yet.')}</p>${cos&&notes?`<p class="ops-sheet-note">${esc(notes)}</p>`:''}<h3>FINAL CHECKS</h3><div class="ops-sheet-checks">${checks.map(k=>`<span>☐ ${esc(k)}</span>`).join('')}</div><footer><div>Technician: __________________________</div><div>Date: __________________</div></footer><div class="ops-paper-bottom">Place inside laptop · QR is the matching RefurbFlow / APEX Diagnostics device identity</div></div>`;}
let printCleanup=null;
function printDocument(markup,title='APEX report',paper='A4'){if(window.ApexReportPreview?.capture){window.ApexReportPreview.capture(markup,title,paper,'report');return;}if(printCleanup)printCleanup();const pane=document.createElement('div');pane.id='opsPrintArea';pane.innerHTML=markup;window.ApexReportBrand.apply(pane);document.body.appendChild(pane);
const style=document.createElement('style');style.id='opsPageSize';style.textContent=`@page{size:${paper};margin:0}`;document.head.appendChild(style);
let done=false;const cleanup=()=>{if(done)return;done=true;window.removeEventListener('afterprint',cleanup);style.remove();pane.remove();printCleanup=null;};printCleanup=cleanup;window.addEventListener('afterprint',cleanup,{once:true});setTimeout(cleanup,45000);window.print();}
