function qcMarkup(id){const a=item(id),j=ops.jobs[id];if(!a||!j)throw Error('A selected device has no refurbishment job for a QC report.');
 const tests=a.diagnosticTests||{};const records=Object.entries(tests).filter(([name,result])=>['pass','fail'].includes(String(result?.status||result).toLowerCase()));
 const content=`<div class="ops-sheet"><header><div><b>APEX / QUALITY CONTROL</b><h1>FINAL DEVICE INSPECTION</h1><small>Report generated ${esc(new Date().toLocaleDateString('en-GB'))}</small></div><div class="ops-paper-qr">${window.ApexAssetLabelQR.qrCodeSvg(window.ApexAssetLabelQR.makePayload(a))}</div></header><h2>${esc(deviceName(a))}</h2><div class="ops-sheet-cols"><span><b>ASSET</b><br>${esc(id)}</span><span><b>SERIAL</b><br>${esc(a.serial||'—')}</span><span><b>STAGE</b><br>${esc(j.status)}</span><span><b>TECHNICIAN</b><br>${esc(j.technician||'Unassigned')}</span></div><h3>REPAIR COMPLETION</h3><table><thead><tr><th>Required item</th><th>Fitted</th><th>Needed</th></tr></thead><tbody>${j.parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.fitted}</td><td>${p.qty}</td></tr>`).join('')||'<tr><td colspan="3">No replacement parts required</td></tr>'}</tbody></table><h3>QUALITY CONTROL CHECKLIST</h3>${checks.map(k=>`<p>${j.qc?.[k]?'☑':'☐'} ${esc(k)}</p>`).join('')}<h3>IMPORTED APEX DIAGNOSTICS RESULTS</h3><table><thead><tr><th>Test</th><th>Result</th></tr></thead><tbody>${records.map(([name,r])=>`<tr><td>${esc(name)}</td><td>${esc(r.status||r)}</td></tr>`).join('')||'<tr><td colspan="2">No completed tests received</td></tr>'}</tbody></table><footer><span>QC approved by: ____________________</span><span>Date: __________________</span></footer></div>`;
return content;}
