function printDiagnosticsReports(ids){
 const selected=ids.map(item);if(selected.some(a=>!a)){notify('A selected device is no longer in inventory. Refresh and try again.');return;}
 const markup=selected.map(a=>{
  const records=Object.entries(a.diagnosticTests||{}).filter(([name,r])=>['pass','fail'].includes(String(r?.status||r).toLowerCase()));
  return '<div class="ops-sheet"><header><div><b>APEX / DIAGNOSTICS</b><h1>DEVICE DIAGNOSTICS REPORT</h1><small>Generated '+esc(new Date().toLocaleDateString('en-GB'))+'</small></div></header><h2>'+esc(deviceName(a))+'</h2><div class="ops-sheet-cols"><span><b>ASSET ID</b><br>'+esc(a.id)+'</span><span><b>SERIAL</b><br>'+esc(a.serial||'Not recorded')+'</span><span><b>GRADE</b><br>'+esc(a.condition||'Not assessed')+'</span><span><b>STATUS</b><br>'+esc(a.status)+'</span></div><h3>RECORDED DIAGNOSTICS</h3><table><thead><tr><th>Test</th><th>Result</th></tr></thead><tbody>'+records.map(([name,r])=>'<tr><td>'+esc(typeof APEX_TEST_LABELS!=='undefined'?(APEX_TEST_LABELS[name]||name):name)+'</td><td>'+esc(String(r?.status||r).toUpperCase())+'</td></tr>').join('')+(records.length?'':'<tr><td colspan="2">No completed diagnostics results recorded.</td></tr>')+'</tbody></table></div>';
 }).join('');printDocument(markup,'Device diagnostics reports','A4');
}
// Wrap existing UI flows to keep job view and hub records synchronized.
const originalOpenAsset=openAsset;openAsset=function(...args){const r=originalOpenAsset(...args);load(true);return r;};
const originalRefresh=refresh;refresh=async function(...args){await originalRefresh(...args);if(!$('appPage').classList.contains('hidden'))await load(true);};
const originalSetPage=setPage;setPage=function(page,force){const result=originalSetPage(page,force);if(result&&pages[page])load(true);return result;};
$('opsPrintJob').onclick=()=>printWorksheet(activeAssetId);
$('reportJobSheet').onclick=()=>{const jobs=sortJobs();showModal('Print job worksheet','APEX / PRINT A4',`<div class="modal-body"><label class="field">Select laptop<select id="opsPrintAsset">${jobs.map(j=>`<option value="${esc(j.assetId)}">${esc(j.assetId)} · ${esc(deviceName(item(j.assetId)))}</option>`).join('')}</select></label><div class="modal-actions"><button class="secondary" type="button" id="opsCancel">Cancel</button><button class="primary" type="button" id="opsPrintSelected">Print A4 worksheet</button></div></div>`);$('opsCancel').onclick=closeModal;$('opsPrintSelected').onclick=()=>{const id=$('opsPrintAsset')?.value;closeModal();printWorksheet(id);};};
